const d=document.getElementById("mobile-menu-btn"),e=document.getElementById("mobile-menu"),s=document.getElementById("hamburger-icon"),t=document.getElementById("close-icon");d?.addEventListener("click",()=>{e?.classList.contains("hidden")?(e?.classList.remove("hidden"),s?.classList.add("hidden"),t?.classList.remove("hidden"),d.setAttribute("aria-expanded","true")):(e?.classList.add("hidden"),s?.classList.remove("hidden"),t?.classList.add("hidden"),d.setAttribute("aria-expanded","false"))});e?.querySelectorAll("a").forEach(n=>{n.addEventListener("click",()=>{e.classList.add("hidden"),s?.classList.remove("hidden"),t?.classList.add("hidden"),d?.setAttribute("aria-expanded","false")})});
